import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import { AddCar } from "../../services/ApiCar";

export default function CardAddVoiture() {
  const history = useHistory();

  const [newCar, setNewCar] = useState({
    matricule: "",
    model: "",
    marque: "",
    libelle: "",
    prix: "",
    prix_jour: "",
    couleur: "",
    disponible: false,
    voiture_image: null,
  });

  const [error, setError] = useState("");

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewCar({ ...newCar, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Vérification simple : tous les champs requis sont-ils remplis ?
    if (
      !newCar.matricule ||
      !newCar.model ||
      !newCar.marque ||
      !newCar.libelle ||
      !newCar.prix ||
      !newCar.prix_jour ||
      !newCar.couleur ||
      !newCar.voiture_image
    ) {
      setError("Veuillez remplir tous les champs obligatoires.");
      return;
    }

    const formData = new FormData();
    for (const key in newCar) {
      formData.append(key, newCar[key]);
    }

    try {
      await AddCar(formData);
      history.push("/CardVoiture"); // redirection après succès
    } catch (err) {
      console.error(err);
      setError("Une erreur s'est produite lors de l'ajout.");
    }
  };

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Add New Car</h6>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        {error && (
          <div className="bg-red-100 text-red-700 px-4 py-2 rounded mb-4">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Car Information</h6>
          <div className="flex flex-wrap">
            {[
              { id: "matricule", label: "Matricule" },
              { id: "model", label: "Model" },
              { id: "marque", label: "Marque" },
              { id: "libelle", label: "Libelle" },
              { id: "prix", label: "Prix", type: "number" },
              { id: "prix_jour", label: "Prix par Jour", type: "number" },
              { id: "couleur", label: "Couleur" },
            ].map(({ id, label, type = "text" }) => (
              <div className="w-full lg:w-6/12 px-4" key={id}>
                <div className="relative w-full mb-3">
                  <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2" htmlFor={id}>
                    {label}
                  </label>
                  <input
                    type={type}
                    id={id}
                    name={id}
                    onChange={handleChange}
                    className="border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full ease-linear transition-all duration-150"
                    placeholder={`Entrer ${label.toLowerCase()}`}
                  />
                </div>
              </div>
            ))}
          </div>

          <hr className="mt-6 border-b-1 border-blueGray-300" />
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Disponibilité & Image</h6>
          <div className="flex flex-wrap">
            <div className="w-full lg:w-4/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2" htmlFor="disponible">
                  Disponible
                </label>
                <input
                  type="checkbox"
                  id="disponible"
                  name="disponible"
                  onChange={(e) => setNewCar({ ...newCar, disponible: e.target.checked })}
                  className="form-checkbox h-5 w-5 text-lightBlue-600"
                />
              </div>
            </div>

            <div className="w-full lg:w-4/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2" htmlFor="voiture_image">
                  Image
                </label>
                <input
                  type="file"
                  id="voiture_image"
                  name="voiture_image"
                  accept="image/*"
                  onChange={(e) => setNewCar({ ...newCar, voiture_image: e.target.files[0] })}
                  className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full ease-linear transition-all duration-150"
                />
              </div>
            </div>
          </div>

          <div className="text-center mt-6">
            <button
              type="submit"
              className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md transition-all duration-150"
            >
              Ajouter la voiture
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
